    const y=Number(date.find(x=>x.type==='year').value),m=Number(date.find(x=>x.type==='month').value),d=Number(date.find(x=>x.type==='day').value);
    const today=Date.UTC(y,m-1,d),weekday=new Date(today).getUTCDay();
