  let publicCache=null,publicCacheAt=0,publicPending=null,publicScope='',publicOverrides=new Set();
  function parseCsv(input,preserve=false){
    input=String(input||'').replace(/^\uFEFF/,'');
    const rows=[];let row=[],cell='',quoted=false;
    for(let i=0;i<input.length;i++){
      const ch=input[i];
      if(ch==='"'){
        if(quoted&&input[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;
      }else if(ch===','&&!quoted){row.push(cell);cell='';}
      else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&input[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell='';}
      else cell+=ch;
    }
    row.push(cell);if(row.some(x=>x!==''))rows.push(row);
    if(!rows.length)return [];
    const keys=rows.shift().map(x=>x.trim());
    return rows.map(r=>Object.fromEntries(keys.map((k,i)=>[k,preserve?(r[i]||''):(r[i]||'').trim()])));
  }

