    if(cloudUID)return Object.fromEntries([["economics",22],["theory",21]].map(([d,n])=>[d,new Set(Array.from({length:n},(_,i)=>i+1).filter(i=>cloudValues["seminar-"+d+"-"+i]==="1"))]));
