  const feedStatus={},feedSaved={},k44FeedAt={};
  const feedSchemas={materials:[['Дисциплина','Название материала','Ссылка на файл','Описание'],['discipline','title','url']],schedule:[['Неделя','День','Начало','Окончание','Дисциплина','Преподаватель','Аудитория','Тип занятия'],['week','weekday','start_time','end_time','subject']],notices:[['Заголовок','Текст','Тип','Дата занятия','Дата публикации'],['title','body']],topics:[['discipline','number','title']]};
  function fromFeed(category,csv){
    if(!csv.trim()||/^\s*</.test(csv))throw Error('Google не вернул CSV');
    const keys=csv.replace(/^\uFEFF/,'').split(/\r?\n/,1)[0].split(',').map(v=>v.trim().replace(/^"|"$/g,''));
    if(!feedSchemas[category].some(schema=>schema.every(k=>keys.includes(k))))throw Error('Неверные заголовки');
    const dayNames=['понедельник','вторник','среда','четверг','пятница','суббота','воскресенье'];
    const isoDate=v=>{v=String(v||'').trim();const m=v.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);if(m)v=m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');return /^\d{4}-\d{2}-\d{2}$/.test(v)?v:'';};
    const time=v=>{const m=String(v||'').match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);return m&&+m[1]<24&&+m[2]<60?m[1].padStart(2,'0')+':'+m[2]:'';};
    return parseCsv(csv).map(r=>{
      if(category==='materials'&&'Дисциплина' in r)return {discipline:r['Дисциплина'],title:r['Название материала'],url:r['Ссылка на файл'],description:r['Описание']};
      if(category==='schedule'&&'Неделя' in r){const w=String(r['Неделя']||'').trim().toLowerCase(),week=/^(a|а)$/.test(w)?'A':/^(b|б)$/.test(w)?'B':/^(обе|both|а\+б|a\+b)$/.test(w)?'both':'';return {week,weekday:dayNames.indexOf(String(r['День']||'').trim().toLowerCase()),start_time:time(r['Начало']),end_time:time(r['Окончание']),subject:r['Дисциплина'],teacher:r['Преподаватель'],room:r['Аудитория'],lesson_type:r['Тип занятия']};}
      if(category==='notices'&&'Заголовок' in r){const type=String(r['Тип']||'').toLowerCase(),d=isoDate(r['Дата публикации']),dt=d?Date.parse(d+'T12:00:00+03:00')/1000:Math.floor(Date.now()/1000);return {title:r['Заголовок'],body:r['Текст'],kind:/отмен|cancel/.test(type)?'cancelled':/перенос|измен|change/.test(type)?'change':'info',lesson_date:isoDate(r['Дата занятия']),created_at:dt};}
      return r;
    });
  }
  async function fetchFeed(url){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8500);try{const r=await fetch(url+(url.includes('?')?'&':'?')+'_ts='+Date.now(),{cache:'no-store',signal:ctrl.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.text();}finally{clearTimeout(timer);}}
  function normalizeRows(category,rows){
    const result=[];
    for(const record of rows){
      if(!record||typeof record!=='object')continue;
      const x={...record};
      if(category==='topics'){
        x.number=Number(x.number);x.defended=/^(1|true|да|yes|защищена|✓)$/i.test(String(x.defended||''));
        x.student=String(x.student||'');
        if(!Number.isInteger(x.number)||!x.title||!['history','theory'].includes(x.discipline))continue;
      }
      if(category==='schedule'){
        x.weekday=Number(x.weekday);
        if(![0,1,2,3,4,5,6].includes(x.weekday)||!x.subject||!x.start_time||!x.end_time||!['A','B','both'].includes(x.week))continue;
      }
      if(category==='notices'){
        if(!x.title||!x.body)continue;
        x.created_at=Number(x.created_at)||Math.floor(Date.now()/1000);
        x.kind=['cancelled','change','info'].includes(x.kind)?x.kind:'info';
      }
      if(category==='materials'){
        if(!x.title||!x.discipline||!/^https:\/\//.test(x.url||''))continue; x.description=String(x.description||'');
      }
      result.push(x);
    }
    return result;
  }
  async function loadPublicData(){
    const scope=activeAccountToken();
    if(publicScope!==scope){publicCache=null;publicCacheAt=0;publicPending=null;publicScope=scope;publicOverrides=new Set();}
    if(publicCache&&Date.now()-publicCacheAt<90000)return publicCache;
    if(publicPending)return publicPending;
    const base=window.KURSOR_STATIC_DATA||{},keys=['notices','materials','topics','schedule'];
    const result={...base,...(publicCache||{})};
    const urls=window.KURSOR_SHEETS||{},statuses=[],overrides=new Set(publicOverrides);
    // Keep private course assignments in memory only; scope checks discard old responses.
    const current=()=>scope===activeAccountToken()&&publicScope===scope&&publicPending===pending;
    const publish=()=>{if(!current())return;for(const k of keys)result[k]=normalizeRows(k,result[k]||[]);publicCache={...result};publicCacheAt=Date.now();window.KURSOR_LAST_SYNC=new Date();window.KURSOR_SYNC_ERRORS=[...statuses];
      for(const k of keys)state[k]=publicCache[k];const old=state.anchor;state.anchor=result.anchor||'2026-11-02';if(old!==state.anchor)state.manualWeek=false;if(!state.manualWeek)state.week=autoWeek()||'A';
      if(state.page==='home')renderHome();if(state.page==='schedule')renderSchedule();if(state.page==='materials')renderMaterials();if(state.page==='courses')renderCourses();
    };
    const pending=Promise.resolve().then(async()=>{
      const server=(async()=>{try{await loadAccountConfig();const d=accountIdentity?(await k43Bootstrap()).content:await accountRequest('/v4/content');if(!current())return;for(const k of keys){if(Array.isArray(d[k])){overrides.add(k);result[k]=d[k];}else if(overrides.delete(k)){result[k]=feedSaved[k]||base[k]||[];}}publicOverrides=new Set(overrides);if(d.anchor)result.anchor=d.anchor;publish();}catch{if(current()){statuses.push('server');}}})();
      const feeds=keys.map(async k=>{if(!urls[k]||overrides.has(k)||(Date.now()-(k44FeedAt[k]||0)<180000&&Object.prototype.hasOwnProperty.call(feedSaved,k))){if(!overrides.has(k)&&Object.prototype.hasOwnProperty.call(feedSaved,k))result[k]=feedSaved[k];return;}k44FeedAt[k]=Date.now();try{const raw=fromFeed(k,await fetchFeed(urls[k])),rows=normalizeRows(k,raw);if(raw.some(r=>Object.values(r).some(v=>String(v??'').trim()))&&!rows.length)throw Error('Данные не распознаны');if(!current())return;feedSaved[k]=rows;feedStatus[k]='ok';if(!overrides.has(k))result[k]=rows;publish();}catch{if(!current())return;statuses.push(k);feedStatus[k]='error';if(!overrides.has(k)&&Object.prototype.hasOwnProperty.call(feedSaved,k)&&!publicCache)result[k]=feedSaved[k];}});
      await Promise.allSettled([server,...feeds]);publish();return current()?publicCache:result;
    }).finally(()=>{if(publicPending===pending)publicPending=null;});
    publicPending=pending;return pending;
  }
  async function publicApi(path,method){
    if(path==='/me')return {name:'Гость группы',role:'student',status:'approved',csrf:''};
    if(path==='/presence')return {ok:true};
    if(method!=='GET')throw new Error('Редактирование доступно только старосте в исходной Google Таблице.');
    const d=await loadPublicData();
    if(path==='/notices')return d.notices;
    if(path==='/materials')return d.materials;
    if(path==='/topics')return {items:d.topics,unresolved:[]};
    if(path==='/schedule')return {lessons:d.schedule,week_a_monday:d.anchor||'2026-11-02'};
    if(path==='/community')return {members:[],server_time:Math.floor(Date.now()/1000)};
    if(path==='/members')return [];
    throw new Error('Неизвестный раздел');
  }

