  document.addEventListener('change',async e=>{const x=e.target;if(x.matches('[data-k4-task]')){const p=k4Personal.find(t=>t.id===x.dataset.k4Task);if(!p)return;x.disabled=true;try{await accountRequest('/v4/personal',{action:'put',item:{...p,done:x.checked}});await k4FetchPersonal();}catch(err){x.checked=!x.checked;toast(err.message);}finally{x.disabled=false;}}if(x.matches('#k4profileForm select[name=id]')){const f=x.form,p=k4AdminData.profiles.find(z=>z.id===x.value),s=k4AdminData.students.find(z=>z.id===x.value);f.elements.name.value=p?.name||s?.name||'';for(const key of ['date','bio','award'])f.elements[key].value=p?.[key]||'';f.elements.photo.value='';f.elements.removePhoto.checked=false;}});
  document.addEventListener('submit',async e=>{const f=e.target;if(!f.id.startsWith('k4'))return;e.preventDefault();const data=Object.fromEntries(new FormData(f)),b=f.querySelector('button[type=submit],button:not([type])');if(b)b.disabled=true;try{switch(f.id){case'k4taskForm':await accountRequest('/v4/personal',{action:'put',item:{id:k4Uid(),kind:'task',title:data.title,subject:data.subject,date:data.date,done:false}});f.reset();await k4FetchPersonal();break;case'k4contentForm':{const category=k4AdminTab,rows=[...(k4AdminData.content[category]??state[category])],i=+data.index;delete data.index;if(category==='schedule')data.weekday=Number(data.weekday);if(category==='topics'){data.number=Number(data.number);data.defended=data.defended==='true';}if(category==='notices')data.created_at=i>=0?rows[i].created_at:Math.floor(Date.now()/1000);if(i<0)rows.push(data);else rows[i]=data;await k4Admin('content',{category,rows});await k4AfterAdmin();break;}case'k4anchorForm':await k4Admin('anchor',{anchor:data.anchor});await k4AfterAdmin();break;case'k4profileForm':{const p={id:data.id,name:data.name,date:data.date,bio:data.bio,award:data.award};if(data.removePhoto)p.photo='';else if(data.photo?.size)p.photo=await k4Picture(data.photo);await k4Admin('profile',{profile:p});await k4AfterAdmin();break;}case'k4answersForm':await k4Admin('answers',{disc:data.disc,items:unpackAnswers(await data.csv.text())});await k4AfterAdmin();break;case'k45photosForm':{const j=JSON.parse(await data.file.text());if(!Array.isArray(j.profiles))throw Error('Неверный файл фотографий');const profiles=j.profiles.filter(p=>k45ValidPhoto(p.photo));if(!profiles.length)throw Error('Файл не содержит фото');const status=$('k45photoImportStatus');let n=0;for(const p of profiles){status.textContent='Восстановление '+n+' / '+profiles.length+'…';await k4Admin('restoreProfiles',{profiles:[{id:String(p.id),name:p.name,photo:p.photo,date:'',bio:'',award:''}]});n++;}status.textContent='Готово: обработано '+n+' фото.';k4ClearPhotos();k43ResetBoot();groupLast=0;void refreshGroup(true);toast('Фото обработаны. Проверь раздел «Наша группа».');break;}case'k4importForm':{const j=JSON.parse(await data.file.text());if(!Array.isArray(j.profiles)||!Array.isArray(j.topics))throw Error('Неверный файл импорта');let n=0;const status=$('k4importStatus');for(let i=0;i<j.profiles.length;){const chunk=[];let size=0;while(i<j.profiles.length&&chunk.length<6){const profile=j.profiles[i],len=JSON.stringify(profile).length;if(chunk.length&&size+len>280000)break;chunk.push(profile);size+=len;i++;}status.textContent=`Восстановление анкет: ${n} / ${j.profiles.length}…`;await k4Admin('restoreProfiles',{profiles:chunk});n+=chunk.length;}status.textContent='Восстановление тем курсовых…';await k4Admin('restoreTopics',{rows:j.topics,correctKeys:j.correctKeys||[]});if(j.answers){for(const disc of ['economics','theory'])if(Array.isArray(j.answers[disc])){status.textContent='Загрузка ответов: '+disc;await k4Admin('answers',{disc,items:j.answers[disc]});}}status.textContent='Импорт успешно завершён.';await k4AfterAdmin();toast('Анкеты, темы и статистика восстановлены');break;}}}catch(err){toast(err.message);if(f.id==='k45photosForm'&&$('k45photoImportStatus'))$('k45photoImportStatus').textContent='Импорт прерван: '+err.message+'; можно повторить.';if(f.id==='k4importForm'&&$('k4importStatus'))$('k4importStatus').textContent='Импорт прерван: '+err.message+'; можно запустить повторно.';}finally{if(b)b.disabled=false;}});
  window.addEventListener('focus',()=>{if(accountIdentity&&state.page==='account'&&Date.now()-k44PersonalAt>60000)void k4FetchPersonal();});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();k4DeferredInstall=e;});
  if('serviceWorker'in navigator&&location.protocol==='https:'){const register=()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});if(document.readyState==='complete')setTimeout(register,500);else window.addEventListener('load',()=>setTimeout(register,500),{once:true});}
  function k4Season(){const m=moscowDay().m,season=m===12||m<=2?'winter':m<=5?'spring':m<=8?'summer':'autumn',enabled=localRead('kursor-season-v1','1')==='1';document.documentElement.dataset.k4Season=enabled?season:'';const band=$('k43SeasonBand');if(band){band.hidden=!enabled;band.dataset.season=season;band.querySelector('b').textContent={winter:'Зимний семестр',spring:'Весна в Курсоре',summer:'Летнее настроение',autumn:'Осень в Курсоре'}[season];band.querySelector('small').textContent={winter:'Тёплых встреч и удачной учёбы',spring:'Новые идеи и новые возможности',summer:'Пусть каждый день будет ярким',autumn:'Время уютных вечеров и новых знаний'}[season];}$('k4SeasonText').textContent='Сейчас: '+{winter:'зима',spring:'весна',summer:'лето',autumn:'осень'}[season];$('k4SeasonToggle').checked=enabled;}
  $('k4SeasonToggle').addEventListener('change',e=>{localWrite('kursor-season-v1',e.target.checked?'1':'0');k4Season();});k4Season();setInterval(k4Season,60000);k4Account();

  (async()=>{try{await loadApp();}catch(err){console.error('Kursor startup:',err);if(window.KURSOR_PUBLIC){$('authView').hidden=true;$('appView').hidden=false;toast('Не удалось загрузить часть данных. Обнови страницу.');}else{$('authView').hidden=false;$('appView').hidden=true;}}})();
